var n=`0702-babenda`;var t=`world-0702`;var a=`BF`;var s=`western-africa`;var r=4;var o=69;var l={en:`Babenda`,ua:`Бабенда`};var d={en:`Babenda is a Burkina Faso classic prepared with white rice, yellow onion, tomato, spinach. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Бабенда, страва кухні країни Буркіна-Фасо зі складниками: білий рис, жовта цибуля, помідор, шпинат. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`white-rice`,170,`g`],[`water`,500,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,130,`g`],[`red-palm-oil`,55,`ml`],[`tomato`,220,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`spinach`,420,`g`],[`peanut`,160,`g`],[`water`,460,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`ground-cumin`,4,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:n,id:t,country:`BF`,region:s,servings:4,minutes:69,title:l,text:d,steps:g};export{a as country,u as default,t as id,o as minutes,s as region,r as servings,n as slug,g as steps,d as text,l as title};